package ai.decisionos.aside;
import android.content.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import android.graphics.Rect;import java.util.*;
final class TossTouchChecks {
 static android.view.accessibility.AccessibilityNodeInfo find(GoalInstrumentation i,String label)throws Exception{for(int attempt=0;attempt<20;attempt++){AccessibilityNodeInfo root=i.getUiAutomation().getRootInActiveWindow();if(root!=null){ArrayDeque<AccessibilityNodeInfo> q=new ArrayDeque<>();q.add(root);while(!q.isEmpty()){AccessibilityNodeInfo n=q.remove();String text=String.valueOf(n.getText()),desc=String.valueOf(n.getContentDescription());Rect r=new Rect();n.getBoundsInScreen(r);if((label.equals(text)||label.equals(desc))&&n.isVisibleToUser()&&!r.isEmpty())return n;for(int c=0;c<n.getChildCount();c++){AccessibilityNodeInfo child=n.getChild(c);if(child!=null)q.add(child);}}}Thread.sleep(200);}throw new AssertionError("Missing visible control: "+label);}
 static void tap(GoalInstrumentation i,String label)throws Exception{Rect b=new Rect();find(i,label).getBoundsInScreen(b);long now=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,b.centerX(),b.centerY(),0),up=MotionEvent.obtain(now,now+75,MotionEvent.ACTION_UP,b.centerX(),b.centerY(),0);down.setSource(InputDevice.SOURCE_TOUCHSCREEN);up.setSource(InputDevice.SOURCE_TOUCHSCREEN);i.getUiAutomation().injectInputEvent(down,true);i.getUiAutomation().injectInputEvent(up,true);down.recycle();up.recycle();Thread.sleep(600);i.waitForIdleSync();}
 static void back(GoalInstrumentation i)throws Exception{i.sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);Thread.sleep(600);i.waitForIdleSync();}
 static void run(GoalInstrumentation i){Bundle out=new Bundle();GoalAgentActivity a=null;try{
 a=(GoalAgentActivity)i.startActivitySync(new Intent(i.getTargetContext(),GoalAgentActivity.class).putExtra("companion_page","홈").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final GoalAgentActivity h=a;TossHomeChecks.waitReady(i,h.chat.companion.tossHome);find(i,"귀가");HomeUiChecks.shot(i,"touch-home.png");
 tap(i,"시안 선택");find(i,"어떤 홈이 더 편한가요?");HomeUiChecks.shot(i,"touch-variants.png");back(i);find(i,"귀가");i.check(h.chat.companion.page.equals("홈"),"OS back dismisses sheet");
 tap(i,"귀가");find(i,"버스·KTX 함께 조회");HomeUiChecks.shot(i,"touch-travel.png");tap(i,"버스·KTX 함께 조회");i.check(h.chat.character.equals("travel")&&h.chat.companion.page.equals("대화"),"OS touch opens travel chat");String[] draft={""};i.runOnMainSync(()->draft[0]=h.chat.input.getText().toString());i.check(draft[0].contains("513"),"transit draft preserved");i.check(!h.chat.running&&!h.chat.submitting,"no request sent");HomeUiChecks.shot(i,"touch-chat.png");
 tap(i,"메뉴 열기");HomeUiChecks.shot(i,"touch-drawer.png");tap(i,"홈");find(i,"중요한 알림");i.check(h.chat.companion.page.equals("홈"),"sidebar returns home");tap(i,"중요한 알림");find(i,"원문과 마감일 확인하기");HomeUiChecks.shot(i,"touch-detail.png");back(i);find(i,"귀가");i.check(h.chat.companion.page.equals("홈"),"OS back dismisses detail");
 out.putString("stream","PASS "+i.checks+" real OS touch checks\n");
 }catch(Throwable e){out.putString("stream","FAIL "+e+"\n");}finally{if(a!=null){GoalAgentActivity h=a;i.runOnMainSync(h::finish);}}i.finish(out.getString("stream","").startsWith("PASS")?-1:0,out);}
}
